package com.yigongbao.backup.restore;
import org.junit.jupiter.api.Test; import java.nio.file.*; import java.util.*; import java.util.zip.*; import static org.assertj.core.api.Assertions.*;
class LocalOrderRestoreServiceTest { @Test void commitOnlyAfterAllAssets(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("a.txt"));o.write(1);o.closeEntry();o.putNextEntry(new ZipEntry("b.txt"));o.write(2);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("a.txt","b.txt"));}public void upload(Session s,String n,java.io.InputStream i){calls.add("u"+n);}public void commit(Session s){calls.add("c");}public void abort(Session s){calls.add("a");}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o")).doesNotThrowAnyException(); assertThat(calls).containsExactly("ua.txt","ub.txt","c"); }
 @Test void publishesEveryZipAssetUploadToTheRestoreListener(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("files/asset-1-导板.stl"));o.write(new byte[]{1,2,3});o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> events=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("asset-1"),Map.of("asset-1","url"),Map.of("asset-1","restore/asset-1-导板.stl"),"digest","PREPARED");}public void upload(Session s,String n,java.io.InputStream i)throws java.io.IOException{i.readAllBytes();}public void commit(Session s){}public void abort(Session s){}}; var listener=new LocalOrderRestoreService.RestoreAssetListener(){public void started(String asset,String entry,String objectKey,long bytes){events.add("start:"+asset+":"+entry+":"+objectKey+":"+bytes);}public void succeeded(String asset,String entry,String objectKey,long bytes){events.add("success:"+asset+":"+entry+":"+objectKey+":"+bytes);}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o",listener)).doesNotThrowAnyException(); assertThat(events).containsExactly("start:asset-1:files/asset-1-导板.stl:restore/asset-1-导板.stl:0","success:asset-1:files/asset-1-导板.stl:restore/asset-1-导板.stl:3"); }
 @Test void mapsPackagedAssetNameBackToManifestIdentity(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("42-report.pdf"));o.write(1);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("42"));}public void upload(Session s,String n,java.io.InputStream i){calls.add(n);}public void commit(Session s){}public void abort(Session s){}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o")).doesNotThrowAnyException(); assertThat(calls).containsExactly("42"); }
 @Test void unknownCommitDoesNotAbortRemoteSession(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("a.txt"));o.write(1);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("a.txt"));}public void upload(Session s,String n,java.io.InputStream i){calls.add("u"+n);}public void commit(Session s){calls.add("c");throw new CommitOutcomeUnknownException("s",new RuntimeException("timeout"));}public void abort(Session s){calls.add("a");}}; assertThatThrownBy(()->new LocalOrderRestoreService(c).restore(z,"o")).isInstanceOf(CommitOutcomeUnknownException.class); assertThat(calls).containsExactly("ua.txt","c"); }
 @Test void committedRemoteSessionIsNotUploadedAgain(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("a.txt"));o.write(1);o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} List<String> calls=new ArrayList<>(); var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("a.txt"),Map.of(),Map.of(),"digest","COMMITTED");}public void upload(Session s,String n,java.io.InputStream i){calls.add("u");}public void commit(Session s){calls.add("c");}public void abort(Session s){calls.add("a");}}; assertThatCode(()->new LocalOrderRestoreService(c).restore(z,"o")).doesNotThrowAnyException(); assertThat(calls).isEmpty(); }
 @Test void inspectsManifestAssetsBeforeStartingRestore(){ Path z; try{z=Files.createTempFile("o",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("manifest.json"));o.write("{\"manifestRevision\":\"rev-1\",\"assets\":[{\"assetIdentity\":\"42\",\"originalFilename\":\"导板.stl\",\"size\":3,\"assetType\":\"file\",\"relations\":[{\"relationKind\":\"ORDER_FILE\"}]}]}".getBytes(java.nio.charset.StandardCharsets.UTF_8));o.closeEntry();o.putNextEntry(new ZipEntry("files/42-导板.stl"));o.write(new byte[]{1,2,3});o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} var c=new OnlineRestoreClient(){public Session prepare(String id){return new Session("s",List.of("42"));}public void upload(Session s,String n,java.io.InputStream i){}public void commit(Session s){}public void abort(Session s){}}; LocalOrderRestoreService.RestorePackageInventory inventory; try{inventory=new LocalOrderRestoreService(c).inspect(z,"31");}catch(Exception e){throw new RuntimeException(e);} assertThat(inventory.manifestRevision()).isEqualTo("rev-1"); assertThat(inventory.assets()).singleElement().satisfies(asset->{assertThat(asset.assetIdentity()).isEqualTo("42");assertThat(asset.fileName()).isEqualTo("导板.stl");assertThat(asset.zipEntryPresent()).isTrue();assertThat(asset.size()).isEqualTo(3L);}); }
 @Test void rejectsEmptyRestorePackageBeforeCreatingOnlineSession(){ Path z; try{z=Files.createTempFile("empty",".zip");try(ZipOutputStream o=new ZipOutputStream(Files.newOutputStream(z))){o.putNextEntry(new ZipEntry("manifest.json"));o.write("{\"assets\":[]}".getBytes(java.nio.charset.StandardCharsets.UTF_8));o.closeEntry();}}catch(Exception e){throw new RuntimeException(e);} var c=new OnlineRestoreClient(){public Session prepare(String id){throw new AssertionError("空包不应创建线上恢复会话");}public void upload(Session s,String n,java.io.InputStream i){}public void commit(Session s){}public void abort(Session s){}}; assertThatThrownBy(()->new LocalOrderRestoreService(c).restore(z,"9")).isInstanceOf(IllegalStateException.class).hasMessageContaining("不含可恢复文件"); }
}
